public static String applyRelativePath(String path, String relativePath) {
    String finalPath = path;
    for (String relativeComponent : relativePath.split("/")) {
        int lastSeparatorIndex = finalPath.lastIndexOf("/");
        if (relativeComponent.equals("..")) {
            finalPath = finalPath.substring(0, lastSeparatorIndex);
        } else if (!relativeComponent.equals(".")) {
            finalPath += relativeComponent + "/";
        }
    }
    return finalPath;
}

